function icon_sprite(): string
{
    $o = '<svg width="0" height="0" style="position:absolute" aria-hidden="true">';
    foreach (ICONS as $n => $b) $o .= '<symbol id="i-' . $n . '" viewBox="0 0 24 24">' . $b . '</symbol>';
    $o .= '<symbol id="i-wa" viewBox="0 0 24 24">' . WA_PATH . '</symbol>';
    return $o . '</svg>';
}

function icon(string $name, string $cls = 'ico'): string
{
    if ($name === '' || ($name !== 'wa' && !isset(ICONS[$name]))) $name = 'check';
    return '<svg class="' . $cls . '" aria-hidden="true"><use href="#i-' . $name . '"/></svg>';
}

/** icon names offered in the admin icon picker */
function icon_names(): array
{
    return array_keys(ICONS);
}
